        static let press = "Press SOS"
        static let pressHelp = "This records that you pressed it and which door your answers point to. It does not call anybody."
        static let recorded = "Pressed at {at}."
        static let areaShared = "The desk can see the area you chose until {ends}. After that nothing keeps where you were."
        static let areaNotShared = "No area was chosen, so the desk sees none."
        static let nextOfKinHeading = "Your next of kin"
        static let noNextOfKin = "You have not nominated a next of kin, so nobody would be told."
        static let standDown = "Stand it down"
        static let stoodDown = "Stood down at {at} · {reason}"
        static let routedEmergencyServices = "Your answers point to emergency services. MyThuso has sent nobody. Call 10177 now, or 112 from a mobile."
        static let routedUrgentVisit = "A cleared nurse is being asked to come. Nobody is on the way until a nurse accepts, and this screen will not say one has."
        static let routedCannotHelp = "MyThuso cannot send anybody for this. Why, and what to do instead, is above."
        static let partnerNotConnected = "No ambulance partner is connected. Pressing SOS here does not reach an ambulance, and nobody is on the way because of it. Call 10177 for an ambulance, or 112 from a mobile."
        static let priority = "No plan puts anybody ahead of somebody more unwell. An SOS from a MyThuso for Mom Premium parent is routed, offered and shown to the desk exactly as anybody else's."
        static let priorityOpenQuestion = "Whether Premium's priority SOS adds anything is a founder question nobody has answered. Until somebody does, nothing on the Safety, Core or Care engine reads a plan when an SOS is pressed."
        static let dispatchWithoutAHuman = "One thing is sent without a person at the desk deciding: an urgent-visit offer to a cleared nurse, through Care's own offer desk and every vetting gate, when somebody presses SOS in the app and the answers route to an urgent visit. Nothing else is sent without a person, and nothing MyThuso sends is ever an ambulance."
    }

    enum DeskText {
        static let heading = "Patients who pressed SOS"
        static let intro = "When SOS was pressed, the door the answers pointed to, the area while it is shared, whether it was stood down, and whether next of kin could be told. Never what was ticked, who pressed it or what plan they hold."
        static let empty = "Nobody has pressed SOS."
        static let raisedAt = "pressed {at}"
        static let age = "{minutes} min"
        static let routedTo = "Door · {outcome}"
        static let readArea = "Read the area"
        static let area = "{area}, shared with the desk until {ends}"
        static let stoodDown = "Stood down at {at} · {reason}"
        static let concern = "Concern with the {owner} until {at}, then the {fallback}, unless somebody takes it on"
        static let concernClosed = "Concern closed · {outcome}"
        static let nextOfKin = "Next of kin"
        static let noNextOfKin = "No next of kin nominated."
        static let attempt = "{status} · try {attempt} of {allowed}, until {ends}"
        static let tryAgain = "Try next of kin again"
    }

    enum NextOfKinText {
        static let heading = "Next of kin"
        static let intro = "Somebody MyThuso may tell, in plain words, that you pressed SOS and when. Nothing else: not why, not what you ticked, not where you are, and nothing from your record."
        static let purposeFrom = "packages/catalog/consent.json#grants.recipientRoles"
        static let alertSays = "{name} pressed SOS in MyThuso at {at}. MyThuso is not an emergency service and has called nobody. If you can, call {name}. If you think it is a life threat, call 10177."
        static let name = "Their name"
        static let nameHelp = "In this preview the name stays in this tab and is forgotten when it closes. The identity service would hold it, and Safety only a reference to it."
        static let nominate = "Nominate"
        static let nominated = "Nominated at {at}, for emergencies only, until {expires}."
        static let asGuardian = "Nominate as a guardian, for somebody else"
        static let withdraw = "Withdraw"
        static let withdrawn = "Withdrawn at {at}. They will not be told anything."
        static let tries = "If you press SOS they are tried once, and the desk may try {retries} more times within {minutes} minutes of the press."
        static let consentWording = "I name this person as my next of kin. If I press SOS, MyThuso may tell them that I pressed it and when. It will not tell them why, what I ticked, where I am or anything from my health record. I can withdraw this at any time, in one action."
        static let consentTick = "I agree to this wording"
    }

    /// The version of the wording a nomination is consented to.
    static let nextOfKinConsentVersion = 1
    /// How long a nomination runs before the patient chooses again: the next-of-kin role's ceiling in consent.json.
    static let nextOfKinNominationDays = 90
    /// The purposes consent.json allows a next-of-kin grant.
    static let nextOfKinPurposes: [String] = ["emergency"]
    static let nextOfKinNeverSays: [String] = ["why they pressed it", "whether any of the eight conditions was ticked, or which", "where they are", "anything from their health record", "which plan they hold"]
    /// The only status an attempt can have while no SMS provider is connected, and why.
    static let nextOfKinStatuses: [SosRefusal] = [
        .init(id: "not-sent", sentence: "Not sent")
    ]
    static let nextOfKinNotSent: [SosRefusal] = [
        .init(id: "sms-not-integrated", sentence: "No SMS provider is connected, so MyThuso could not tell them. This records that it would have.")
    ]
    static let routeRefusals: [SosRefusal] = [
        .init(id: "wearable-alone", sentence: "A consumer wearable alone does not raise an SOS dispatch."),
        .init(id: "sos-channel-unknown", sentence: "That is not a way SOS can be pressed."),
        .init(id: "sos-area-not-on-the-list", sentence: "Choose the area from the list, or choose somewhere else."),
        .init(id: "no-priority-by-plan", sentence: "No plan puts anybody ahead of somebody more unwell. An SOS is routed and offered the same way whatever plan the person holds."),
        .init(id: "sos-carries-nothing-else", sentence: "An SOS carries how it was pressed, the area chosen from the list and two answers. Nothing else is taken with it: not where the phone is, and not what is wrong."),
        .init(id: "stand-down-without-reason", sentence: "Choose one of the reasons on the screen to stand it down. Nobody asks you to explain, and it costs nothing."),
        .init(id: "sos-already-stood-down", sentence: "That SOS is already stood down. If you need help again, press SOS again."),
        .init(id: "no-sos-of-yours", sentence: "There is no SOS of yours by that reference."),
        .init(id: "sos-list-takes-no-filter", sentence: "The SOS list is read whole. It is never narrowed or sorted by who pressed, what plan they hold or where."),
        .init(id: "area-not-chosen", sentence: "No area was chosen for this SOS, so there is nothing to show."),
        .init(id: "nomination-without-consent", sentence: "Next of kin are nominated with explicit consent and a scope, or not at all."),
        .init(id: "nomination-purpose-not-allowed", sentence: "A next of kin is nominated for emergencies and nothing else."),
        .init(id: "nominations-read-by-their-patient", sentence: "Only the patient who made them reads their next-of-kin nominations."),
        .init(id: "no-nomination-of-yours", sentence: "There is no nomination of yours by that reference."),
        .init(id: "nomination-withdrawn", sentence: "That nomination was withdrawn. Nobody is told anything through it."),
        .init(id: "nomination-expired", sentence: "That nomination has run out. The patient chooses again before anybody is told anything through it."),
        .init(id: "no-such-nomination", sentence: "There is no nomination by that reference."),
        .init(id: "nomination-not-for-this-sos", sentence: "That nomination is not one the person who pressed this SOS made."),
        .init(id: "alert-after-stand-down", sentence: "That SOS was stood down. Nobody is told about an SOS the person stopped."),
        .init(id: "alert-window-closed", sentence: "Next of kin are tried only inside the window the SOS was pressed under, and it has closed."),
        .init(id: "alert-tries-used", sentence: "Next of kin have been tried as many times as this SOS allows."),
        .init(id: "dispatch-without-a-human", sentence: "Nothing is dispatched without a human, except for an unresponsive patient or an SOS."),
        .init(id: "next-of-kin-see-clinical-detail", sentence: "Next of kin see plain language, never clinical detail."),
        .init(id: "location-kept-after-the-window", sentence: "A location is not kept after the incident window."),
        .init(id: "no-such-sos", sentence: "There is no SOS by that reference."),
        .init(id: "guardian-authority-not-proven", sentence: "A guardian cannot nominate, withdraw or alert a next of kin for somebody else. Guardian authority is not proven, and MyThuso cannot prove it yet.")
    ]
